{"function": "() => {
    // Find Discography section
    const discographyHeading = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.trim() === 'Discography');
    if (!discographyHeading) return { error: 'Discography heading not found' };

    // Get all tables after this heading until next h2
    const tables = [];
    let nextElement = discographyHeading.nextElementSibling;
    while (nextElement && nextElement.tagName !== 'H2') {
        if (nextElement.tagName === 'TABLE') {
            tables.push(nextElement);
        }
        nextElement = nextElement.nextElementSibling;
    }

    // If not enough tables, maybe tables are inside divs
    // Alternative: select all tables with class wikitable within the section
    const section = discographyHeading.closest('div') || discographyHeading.parentNode;
    const wikiTables = section.querySelectorAll('table.wikitable');

    const result = {};
    if (wikiTables.length >= 4) {
        // Assume order: Studio albums, EPs, Live albums, Compilation albums
        const types = ['Studio albums', 'EPs', 'Live albums', 'Compilation albums'];
        types.forEach((type, idx) => {
            const table = wikiTables[idx];
            const rows = Array.from(table.querySelectorAll('tr')).slice(1); // skip header row
            const albums = rows.map(row => {
                const cells = row.querySelectorAll('td');
                if (cells.length >= 2) {
                    const year = cells[0].textContent.trim();
                    const details = cells[1].textContent.trim();
                    // Extract album title and label
                    // Format might be "Album Title Label: Label"
                    return { year, details };
                }
                return null;
            }).filter(a => a);
            result[type] = albums;
        });
    } else {
        // Fallback: just get all rows from all tables
        const allRows = [];
        wikiTables.forEach(table => {
            const rows = Array.from(table.querySelectorAll('tr')).slice(1);
            rows.forEach(row => {
                const cells = row.querySelectorAll('td');
                if (cells.length >= 2) {
                    const year = cells[0].textContent.trim();
                    const details = cells[1].textContent.trim();
                    allRows.push({ year, details });
                }
            });
        });
        result.all = allRows;
    }

    return result;
}"}

