            const cells = rows[i].querySelectorAll('td');
            if (cells.length >= 2) {
                const year = cells[0].textContent.trim();
                // Extract album title and label from second cell
                const detailsCell = cells[1];
                // Get italic element for album title
                const italic = detailsCell.querySelector('i');
                let title = '';
                if (italic) {
                    title = italic.textContent.trim();
                } else {
                    // maybe title is just text before <ul>
                    const clone = detailsCell.cloneNode(true);
                    const ul = clone.querySelector('ul');
                    if (ul) ul.remove();
                    title = clone.textContent.trim();
                }
                // Get label
                const labelLi = detailsCell.querySelector('li');
                let label = '';
                if (labelLi) {
                    label = labelLi.textContent.replace('Label:', '').trim();
                }
                albums.push({ year, title, label });
            }
        }
        result[type] = albums;
    });

    return result;
}"}

